injectJs:
(function(){
  function hide(){
    var s='.home_menu,.rightlistwrap,.comment,.adv,#loginbox,.operate,.mui-scroll-wrapper,.vbadv,.ulist_loading,.ulist_tip';
    document.querySelectorAll(s).forEach(function(e){e.style.display='none';});
    var ck=document.getElementById('ckplays1');
    if(ck){ck.style.cssText='position:fixed;top:0;left:0;width:100vw;height:100vh;margin:0;z-index:1;background:#000;';}
    var vi=document.querySelector('.video_info'); if(vi){vi.style.zIndex='5';}
    document.documentElement.style.overflow='hidden';
    document.body.style.overflow='hidden';
    document.body.style.background='#000';
  }
  hide();
  var t=setInterval(hide,600);
  setTimeout(function(){clearInterval(t);},12000);
  setTimeout(function(){
    var v=document.querySelector('#ckplays1 video');
    if(v){v.muted=true;var p=v.play();if(p&&p.catch){p.catch(function(){});}}
  },1500);
})();

